pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress) public {
        // choose a non-empty caddress so any low-level call path is well-defined;
        // the distinguishing scenario is the EMPTY _tos array, built from a fuzzed length
        uint256 n = 0; // admissible domain includes the empty batch
        address[] memory tos = new address[](n);
        uint256[] memory vals = new uint256[](n);

        bool ok;
        try c.transfer(from, caddress, tos, vals) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a transfer with an empty recipient list is rejected (reverts),
        // it never reports success.
        assertTrue(ok == false, "empty batch must revert");
